def expand(items, w):
    out = []
    for it in items:
        if it == 'W':
            out.extend(w)
        elif it[0] == 'R':
            out.extend(SP(it[1]))
        else:
            out.append((it[1], it[2]))
    return tuple(out)


def expand_cfg(cfg, w):
    st, pb, A, g0, s, items, G = cfg
    return (st, pb, A, g0, s, expand(items, w), G)



def waypoints_rle(j, b):
    """The full asserted waypoint chain TOP14 -> ... -> TOP15
    (plus the r15' = 2 / 4 / 6 and band closing waypoints), in
    run-length form.  Kept unexpanded -- at this phase's scale
    one expanded chain is ~800 GB of tuples."""
    j15 = j - 135985239
    tail = (('P', 1, 1), ('R', b - 1))
    pts = []
    pts.append(('C', TOP14F, 74737818, 135985236, 2,
                (('P', 2 * j - 2, 2),) + tail, 1))
    pts.append(('B', TOP14F, 74737817, 1, 135985236,
                (('P', 2, 2), ('P', 2 * j - 2, 2)) + tail, 1))
    pts.append(('C', F15, 135985236, 1, 2,
                (('P', 2 * j - 4, 2),) + tail, 1))
    pts.append(('B', F15, 135985236, 1, 4,
                (('P', 2 * j - 4, 2),) + tail, 1))
    pts.append(('C', F15, 135985236, 3, 2,
                (('P', 2 * j - 6, 2),) + tail, 1))
    pts.append(('C', F15, 0, 3, 2, (('R', 135985236), 'W'), 1))
    pts.extend(CASCADE61_WPS)
    # TOP15 state reached; closing waypoints by r15' = 2 * j15.
    if j15 == 1:
        pts.append(('B', (147491796,) + TOP15F, 271970480, 1, 3,
                    (('R', b - 1),), 1))
    if j15 == 2:
        pts.append(('C', TOP15F, 147491795, 271970478, 2,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', TOP15F, 147491794, 1, 271970478,
                    (('P', 2, 2), ('P', 2, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', (271970479, 147491795) + TOP15F, 3, 1, 3,
                    (('R', b - 1),), 1))
    if j15 == 3:
        pts.append(('C', TOP15F, 147491795, 271970478, 2,
                    (('P', 4, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', TOP15F, 147491794, 1, 271970478,
                    (('P', 2, 2), ('P', 4, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('C', F16, 271970478, 1, 2,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', F16, 271970478, 1, 4,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', (271970479, 147491795) + TOP15F, 5, 1, 3,
                    (('R', b - 1),), 1))
    if j15 >= 4:
        pts.append(('C', TOP15F, 147491795, 271970478, 2,
                    (('P', 2 * j15 - 2, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', TOP15F, 147491794, 1, 271970478,
                    (('P', 2, 2), ('P', 2 * j15 - 2, 2),
                     ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('C', F16, 271970478, 1, 2,
                    (('P', 2 * j15 - 4, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', F16, 271970478, 1, 4,
                    (('P', 2 * j15 - 4, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('C', F16, 271970478, 3, 2,
                    (('P', 2 * j15 - 6, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', F16, 271970478, 1, 2 * j15 - 2,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
    return pts


def check_chain(j, b, cap=120000000):
    """check_chain with lazy waypoint expansion (the Phase 56
    scale forbids materialising the whole chain).  Matching,
    skip recording and lemmastep replay verification are
    hsim55's, verbatim in behaviour."""
    rle = waypoints_rle(j, b)
    w = W(2 * (j - 135985239), b)
    N = len(rle)
    cache = {}

    def target(k):
        if k not in cache:
            if len(cache) > 24:
                cache.clear()
            cache[k] = norm(expand_cfg(rle[k], w))
        return cache[k]

    pos = -1
    status = fin = None
    used = set()
    src = TOP14(j, b)
    anchor = norm(src)
    skips = []  # (anchor, [skipped waypoints], landing)
    for rec in swalk(src, max_steps=cap):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            status, fin, used = rec[1], rec[2], rec[3]
            break
        if pos + 1 < N:
            if _matches(rec, target(pos + 1)):
                pos += 1
                anchor = target(pos)
            else:
                for k in range(pos + 2, min(pos + 9, N)):
                    if _matches(rec, target(k)):
                        skips.append((anchor,
                                      [target(t)
                                       for t in range(pos + 1, k)],
                                      target(k)))
                        pos = k
                        anchor = target(pos)
                        break
    assert pos == N - 1, \
        'j=%d b=%d: waypoint %d missing: %s' \
        % (j, b, pos + 1, fmt(target(pos + 1)))
    for (anchor, skipped, landing) in skips:
        targets = skipped + [landing]
        ti = 0
        cfg = anchor
        steps = 0
        while ti < len(targets) and steps < 200000:
            hit = lemmastep(cfg)
            assert hit is not None and hit[1] is not None, \
                ('verify replay unmatched', cfg)
            cfg = hit[1]
            steps += 1
            if norm(cfg) == targets[ti]:
                ti += 1
        assert ti == len(targets), \
            'j=%d b=%d: skipped waypoint not verified: %s' \
            % (j, b, fmt(targets[ti]))
    return status, fin, pos, used


def front_check(j, b):
    """The front segment TOP14(j, b) -> DIP14 spine (waypoints
    0..5), with check_chain's skip recording + lemmastep
    replay verification and early exit at the spine."""
    rle = waypoints_rle(j, b)
    w = W(2 * (j - 135985239), b)
    pts = [norm(expand_cfg(c, w)) for c in rle[:6]]
    pos = -1
    anchor = norm(TOP14(j, b))
    skips = []
    for rec in swalk(TOP14(j, b), max_steps=20000000):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            break
        if pos + 1 < len(pts):
            if _matches(rec, pts[pos + 1]):
                pos += 1
                anchor = pts[pos]
            else:
                for k in range(pos + 2, min(pos + 9, len(pts))):
                    if _matches(rec, pts[k]):
                        skips.append((anchor, pts[pos + 1:k],
                                      pts[k]))
                        pos = k
                        anchor = pts[pos]
                        break
        if pos == len(pts) - 1:
            break
    assert pos == len(pts) - 1, \
        'front j=%d b=%d: waypoint %d missing' % (j, b, pos + 1)
    for (a0, skipped, landing) in skips:
        targets = skipped + [landing]
        ti = 0
        cfg = a0
        steps = 0
        while ti < len(targets) and steps < 200000:
            hit = lemmastep(cfg)
            assert hit is not None and hit[1] is not None, \
                ('front replay unmatched', cfg)
            cfg = hit[1]
            steps += 1
            if norm(cfg) == targets[ti]:
                ti += 1
        assert ti == len(targets), \
            'front j=%d b=%d: skipped waypoint not verified' \
            % (j, b)


def TOP15(j15, b):
    return ('B', TOP15F, 147491795, 1, 271970479,
            ((2 * j15, 2), (1, 1)) + tuple(SP(b - 1)), 1)


def main():
    """Execution structure (Phase 61 scale): NO span-sliced
    walk queues were built this phase (the Phase 56/57/58
    queues' remainders are still open; see
    build-logs-61/hsim61-parts-summary.txt).  Parts 2, 3, 4
    below are executed directly by phase61-work/finals61.py
    (walks from the TOP15 state, whose stack is just W).
    Part 1 (the canonical chain), Part 1b (the junk-tail
    probe) and Part 1c (front segments) are NOT executed
    this phase: the cascade segment is verified by the
    classifier chains (chain61_135985240_2/3.jsonl, labels
    and abstracted targets identical) and by the Rocq
    CASCADE61 lemma itself; the in-process front_check
    fails at the spine waypoint by design (the DIPGRIND
    descent yields ~272M walk records, over its 20M cap),
    exactly as in Phases 58-60.  Running this main()
    monolithically would re-execute Part 1 and 1b
    in-process (many hours at this scale)."""
    fails = 0
    used = set()
    # Part 1: the canonical full waypoint chain (135985240, 2).
    try:
        status, fin, pos, u = check_chain(135985240, 2)
        used.update(u)
        print('PASS chain j=135985240 b=2: %d waypoints in order, '
              'walk %s' % (len(waypoints_rle(135985240, 2)), status),
              flush=True)
    except AssertionError as e:
        fails += 1
        print('FAIL', e, flush=True)
    # Part 1b: CASCADE61 is tail-general -- junk tail probe.
    w0 = ((7, 2), (1, 1), (3, 2), (1, 2))
    src = ('C', F15, 0, 3, 2, tuple(SP(135985236)) + w0, 1)
    top15 = norm(('B', TOP15F, 147491795, 1, 271970479, w0, 1))
    ok = False
    for rec in swalk(src, max_steps=120000000):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            break
        if norm(rec) == top15:
            ok = True
            break
    print(('PASS' if ok else 'FAIL'),
          'tail-generality: TOP15 shape reached with junk tail',
          flush=True)
    fails += 0 if ok else 1
    # Part 1c: front segments at the other chain points.
    for (j, b) in [(135985240, 3), (135985241, 2), (135985242, 2),
                   (200000000, 2), (407955720, 2)]:
        try:
            front_check(j, b)
            print('PASS front segment j=%d b=%d: TOP14 -> DIP15 '
                  'spine' % (j, b), flush=True)
        except AssertionError as e:
            fails += 1
            print('FAIL', e, flush=True)
    # Part 2: TOP15-closing finals (walks from the TOP15
    # state, whose stack is just W).
    F16p = (147491796,) + TOP15F
    F17p = (271970479, 147491795) + TOP15F
    finals = {
        (1, 2): (F16p, 271970481),
        (1, 3): (F16p, 271970482),
        (2, 2): (F17p, 4),
        (2, 3): (F17p, 5),
        (3, 2): (F17p, 6),
        (3, 3): (F17p, 7),
        (1000000, 3): (F17p, 2000001),
        (271970481, 2): (F17p, 543940962),
    }
    for (j15, b), (fr, A) in sorted(finals.items()):
        status = fin = None
        for rec in swalk(TOP15(j15, b), max_steps=120000000):
            if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
                status, fin, u = rec[1], rec[2], rec[3]
                used.update(u)
                break
        want = ('B', tuple(fr), A, 1, 2 * b + 1, (), 1)
        ok = status == 'DONE' and norm(fin) == want
        print(('PASS' if ok else 'FAIL'),
              'TOP15 final j15=%d b=%d: %s (want A=%d frame %s)'
              % (j15, b, fmt(fin), A, list(fr)), flush=True)
        fails += 0 if ok else 1
    # Part 3: the sixteenth fence from the TOP15 state --
    # r15' >= 543940964 takes DIPGRIND at 271970478 (j15 is TOP15's
    # parameter).
    for (j15, b) in [(271970482, 2), (271970483, 2), (200000000, 2)]:
        g16 = norm(('C', F16, 271970478, 3, 2,
                    ((2 * j15 - 6, 2), (1, 1)) + tuple(SP(b - 1)), 1))
        dip16 = norm(('C', F16, 0, 3, 2,
                      tuple(SP(271970478))
                      + ((2 * j15 - 543940962, 2), (1, 1))
                      + tuple(SP(b - 1)), 1))
        seen_g16 = seen_dip16 = False
        for rec in swalk(TOP15(j15, b), max_steps=120000000):
            if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
                break
            n = norm(rec)
            if n == g16:
                seen_g16 = True
            elif seen_g16 and n == dip16:
                seen_dip16 = True
                break
        ok = seen_g16 and seen_dip16
        print(('PASS' if ok else 'FAIL'),
              'fence j15=%d: GRIND16 then sixteenth DIPGRIND '
              'landing occur (r15p=%d)' % (j15, 2 * j15),
              flush=True)
        fails += 0 if ok else 1
    # Part 4: primitive-step audit over the terminating
    # walks.
    bad = used - PROVED_RULES
    print(('PASS' if not bad else 'FAIL'),
          'primitive rules used %s all in PROVED_RULES'
          % (sorted(used),), flush=True)
    fails += 0 if not bad else 1
    print()
    print('ALL PHASE 61 CHECKS PASS' if fails == 0
          else '%d FAILURES' % fails)
    return fails


if __name__ == '__main__':
    sys.exit(1 if main() else 0)
